import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

/** Multi-turn order desk agent: answers order status, delivery date and tracking questions. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers customer questions about their orders: status, delivery date and tracking code.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so. ' +
    'Keep replies to one or two sentences. Use what the customer told you earlier in the conversation, such as their name or order id.',
  tools: [lookupOrder],
});
